const items = $input.all();
const raw = items[0].json;
const jobs = Array.isArray(raw) ? raw.slice(1) : [];

return jobs
  .filter(j => j && j.id)
  .filter(j => {
    const tags = (j.tags || []).map(t => t.toLowerCase());
    const title = (j.position || '').toLowerCase();
    const keywords = ['devops','sre','platform','cloud','kubernetes','terraform','infrastructure','reliability'];
    return keywords.some(k => tags.includes(k) || title.includes(k));
  })
  .map(j => ({
    json: {
      external_id: String(j.id),
      source: 'remoteok',
      title: j.position || '',
      company: j.company || 'Unknown',
      location: j.location || 'Remote',
      is_remote: true,
      url: j.url || `https://remoteok.com/jobs/${j.id}`,
      description: j.description || '',
      required_skills: j.tags || [],
      posted_at: j.date ? new Date(j.date * 1000).toISOString() : null,
      salary_min: j.salary_min || null,
      salary_max: j.salary_max || null,
      currency: 'USD'
    }
  }));

const jobs = $input.all().map(i => i.json);
if (jobs.length === 0) return [];
return [{ json: { source: 'remoteok', jobs } }];

const result = $input.first().json;
console.log(`✓ RemoteOK ingest: received=${result.received} inserted=${result.inserted} skipped=${result.skipped}`);
return $input.all();
